public class Main {
    static int islandPerimeter(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int perimeter = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 1) {
                    perimeter += 4;                                          // default contribution
                    if (r > 0 && grid[r - 1][c] == 1) perimeter -= 2;           // shared edge above
                    if (c > 0 && grid[r][c - 1] == 1) perimeter -= 2;           // shared edge to the left
                }
            }
        }
        return perimeter;
    }
}

